import 'package:asn1lib/asn1lib.dart';

void main() {
  var sequence = ASN1Sequence();
  sequence.add(ASN1Integer(42));
  sequence.add(ASN1OctetString('test'));
  var bytes = sequence.encodedBytes;

  var parser = ASN1Parser(bytes);
  var decodedSequence = parser.nextObject() as ASN1Sequence;
}
